-- ============================================
-- LUMA — Thème 17 : LONG 3/3 x4 (DERNIER SCÉNARIO DU PROJET !) — Un entretien avec un coach sportif professionnel
-- ============================================


update scenarios set content = '{"characters": {"coach": "le coach professionnel"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coach", "text": "Thanks for coming in. So, tell me about your athletic background so far.", "text_fr": "Merci d''être venu. Alors, parlez-moi de votre parcours athlétique jusqu''ici.", "choices": [{"text": "I''ve been competing at an amateur level for five years, always chasing the next level.", "text_fr": "Je fais de la compétition au niveau amateur depuis cinq ans, toujours à la recherche du niveau suivant.", "next": "n2"}, {"text": "Honestly, self-taught mostly, but I''ve hit a plateau I can''t seem to break through.", "text_fr": "Honnêtement, autodidacte surtout, mais j''ai atteint un plateau que j''arrive pas à dépasser.", "next": "n2b"}]}, "n2": {"speaker": "coach", "text": "Five years of dedication says a lot. What''s driving you to seek coaching now?", "text_fr": "Cinq ans de dévouement en dit long. Qu''est-ce qui vous pousse à chercher un coaching maintenant ?", "choices": [{"text": "I feel like I''ve maxed out what I can do alone, I need expert guidance.", "text_fr": "J''ai l''impression d''avoir maximisé ce que je peux faire seul, j''ai besoin de conseils d''expert.", "next": "n3"}]}, "n2b": {"speaker": "coach", "text": "Plateaus are frustrating, but they''re often a sign you''re ready for real structure.", "text_fr": "Les plateaux sont frustrants, mais c''est souvent un signe que vous êtes prêt pour une vraie structure.", "choices": [{"text": "That makes sense, I think I''ve been improvising for too long.", "text_fr": "Ça se comprend, je pense que j''improvise depuis trop longtemps.", "next": "n3"}]}, "n3": {"speaker": "coach", "text": "Let''s talk goals. What does success look like for you in the next year?", "text_fr": "Parlons objectifs. À quoi ressemble le succès pour vous dans l''année à venir ?", "choices": [{"text": "Qualifying for regional competitions would be huge for me.", "text_fr": "Se qualifier pour les compétitions régionales serait énorme pour moi.", "next": "n4"}, {"text": "Honestly, just consistent, measurable improvement week over week.", "text_fr": "Honnêtement, juste une amélioration constante et mesurable semaine après semaine.", "next": "n4"}]}, "n4": {"speaker": "coach", "text": "Both are realistic with the right plan. What does your current training look like?", "text_fr": "Les deux sont réalistes avec le bon plan. Votre entraînement actuel ressemble à quoi ?", "choices": [{"text": "Pretty inconsistent, honestly. Some weeks intense, others barely anything.", "text_fr": "Assez incohérent, honnêtement. Certaines semaines intenses, d''autres presque rien.", "next": "n5"}]}, "n5": {"speaker": "coach", "text": "That inconsistency is likely why you''ve plateaued. Structure will make a huge difference.", "text_fr": "Cette incohérence est probablement pourquoi vous avez atteint un plateau. La structure va faire une énorme différence.", "choices": [{"text": "That''s honestly a relief to hear — I thought maybe I''d hit my ceiling.", "text_fr": "Ça soulage honnêtement d''entendre ça — je pensais peut-être avoir atteint mon plafond.", "next": "n6"}]}, "n6": {"speaker": "coach", "text": "Not even close. Let''s talk about what a structured week would realistically look like for you.", "text_fr": "Pas du tout. Parlons de ce à quoi ressemblerait réalistement une semaine structurée pour vous.", "choices": [{"text": "I''m all ears, I want to actually commit this time.", "text_fr": "Je suis tout ouïe, je veux vraiment m''engager cette fois.", "next": "n7"}]}, "n7": {"speaker": "coach", "text": "Four structured sessions weekly, with proper recovery days built in, non-negotiable.", "text_fr": "Quatre séances structurées par semaine, avec des jours de récupération appropriés intégrés, non négociables.", "choices": [{"text": "That sounds intense but manageable. I''m ready for that commitment.", "text_fr": "Ça semble intense mais gérable. Je suis prêt pour cet engagement.", "next": "n8"}, {"text": "Could we start a bit lighter and build up? I don''t want to burn out early.", "text_fr": "On pourrait commencer un peu plus léger et monter en puissance ? Je veux pas m''épuiser trop tôt.", "next": "n8"}]}, "n8": {"speaker": "coach", "text": "Smart thinking either way. Sustainability matters more than initial intensity.", "text_fr": "Bonne réflexion dans les deux cas. La durabilité compte plus que l''intensité initiale.", "choices": [{"text": "I really appreciate that you''re thinking long-term with me.", "text_fr": "J''apprécie vraiment que vous pensiez à long terme avec moi.", "next": "n9"}]}, "n9": {"speaker": "coach", "text": "That''s the only way real progress sticks. Quick fixes rarely last in this sport.", "text_fr": "C''est la seule façon dont le vrai progrès dure. Les solutions rapides durent rarement dans ce sport.", "choices": [{"text": "This conversation alone has given me more clarity than months of training alone.", "text_fr": "Cette conversation à elle seule m''a donné plus de clarté que des mois d''entraînement seul.", "next": "n10"}]}, "n10": {"speaker": "coach", "text": "That''s exactly what good coaching should do. So, shall we get started together?", "text_fr": "C''est exactement ce qu''un bon coaching devrait faire. Alors, on commence ensemble ?", "choices": [{"text": "Absolutely, I''m fully committed. Let''s build something great.", "text_fr": "Absolument, je suis pleinement engagé. Construisons quelque chose de génial.", "next": "end_coached"}]}, "end_coached": {"speaker": "coach", "text": "That''s what I like to hear. Welcome aboard — let''s break through that plateau together.", "text_fr": "C''est ce que j''aime entendre. Bienvenue à bord — brisons ce plateau ensemble.", "end": true, "ending_label": "Coaching professionnel entamé avec clarté et motivation 🏅🤝"}}}'::jsonb, is_playable = true
where title = 'Un entretien avec un coach sportif professionnel'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
